        if c == 40:
            position += 1
            result = expression()
            if position >= len(pattern) or pattern[position] != 41:
                raise InvalidInput('unclosed group')
            position += 1
            return result
        if c == 46:
            position += 1
            return ('char', ALPHABET)
        if c == 91:
            position += 1
            complement = position < len(pattern) and pattern[position] == 94
            if complement:
                position += 1
            members = set()
